extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve essere valida"):
		return
	var player := find_by_name(main, "Player") as CharacterBody2D
	if not check("player", player != null, "Il nodo Player deve essere presente"):
		return
	player.position = Vector2(400, 480)
	await wait_physics_frames(10)
	await hold_action("crouch", 15)
	check("crouch_stop", player.velocity.x == 0.0, "Quando accovacciato la velocità orizzontale deve essere zero (velocity.x = %.1f)" % player.velocity.x)

